  const tr = (s, lang) => dict[lang]?.[s] || s;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const repairStore = window.FixiRepairStore;
