    section.querySelector('#demo-language').value=lang(); section.querySelector('#demo-language').addEventListener('change',e=>{applyLanguage(e.target.value);window.dispatchEvent(new CustomEvent('fixidz:language-changed',{detail:{language:e.target.value}}));toast(tr('Language preference saved.',e.target.value));});
